import { test, expect } from '@playwright/test';

test.use({ storageState: '../auth/user.json' });

test.describe('2. Бизнес-профиль — встроенная карта', () => {
  test('2.2 Вошедший пользователь видит карту-картинку из static-map без API-ключа @desktop @prod-safe (#6a7c8dc36076099644cfa2b8)', async ({ page }) => {
    // 1. Если сессия user не авторизована (уводит на /welcome) — test.skip с причиной.
    await page.goto('/');
    test.skip(/\/(welcome|sign-in)/.test(page.url()), 'Сессия user не авторизована: npm run qa-login:manual -- user');

    // 2. Начать ждать ответ static-map, затем открыть `/u/MM9548`.
    const staticMapResponse = page.waitForResponse((r) => r.url().includes('static-map'));
    await page.goto('/u/MM9548');

    // 3. Дождаться секции Location.
    await expect(page.getByRole('heading', { name: /Location|מיקום/ })).toBeVisible();

    // Ответ static-map успешный, ключа в URL нет
    const response = await staticMapResponse;
    expect(response.ok()).toBeTruthy();
    expect(response.url()).not.toMatch(/key=|AIza/);

    // Картинка data:image/png и адрес рядом
    await expect(page.locator('img[src^="data:image/png"]').first()).toBeVisible();
    await expect(page.getByText(/bat yam/i).first()).toBeVisible();
  });
});
